"""Original bilingual teaching copy for the internal level-three catalogue.

Each concept is (id, German title, English title, German explanation,
English explanation, original schematic score). Scores are teaching models,
not transcriptions or claims about historical sound or instrumentation.
"""

CONCEPTS = {
    "modes": [
        ("ionian", "Ionisch", "Ionian", "Ionisch hat dieselbe Intervallfolge wie die Durtonleiter: 2–2–1–2–2–2–1 Halbtöne. Der Grundton bleibt der Bezugspunkt; bloß auf einer anderen Taste zu beginnen beschreibt noch keinen hörbaren Modus.", "Ionian has the major-scale interval pattern: 2–2–1–2–2–2–1 semitones. The tonic remains the point of reference; merely starting on another key does not establish a heard mode.", "treble | 4/4 | C4/4 D4/4 E4/4 F4/4 | G4/4 A4/4 B4/4 C5/4"),
        ("dorian", "Dorisch", "Dorian", "Dorisch hat gegenüber natürlichem Moll eine erhöhte sechste Stufe. Über D ergibt das D–E–F–G–A–H–C–D; die Tonika D muss musikalisch erkennbar bleiben.", "Dorian differs from natural minor by its raised sixth degree. On D it gives D–E–F–G–A–B–C–D; D must remain audible as the tonic.", "treble | 4/4 | D4/4 E4/4 F4/4 G4/4 | A4/4 B4/4 C5/4 D5/4"),
        ("mixolydian", "Mixolydisch", "Mixolydian", "Mixolydisch hat gegenüber Dur eine erniedrigte siebte Stufe. G–A–H–C–D–E–F–G ist ein Beispiel mit G als Zentrum, nicht einfach eine C-Dur-Tonleiter ohne Bezugston.", "Mixolydian differs from major by its lowered seventh degree. G–A–B–C–D–E–F–G is an example centred on G, rather than an uncentred C-major collection.", "treble | 4/4 | G4/4 A4/4 B4/4 C5/4 | D5/4 E5/4 F5/4 G5/4"),
        ("aeolian", "Äolisch", "Aeolian", "Äolisch entspricht natürlichem Moll mit der Folge 2–1–2–2–1–2–2. Die erhöhte Leittonstufe des harmonischen Molls gehört nicht zu diesem Grundmuster.", "Aeolian corresponds to natural minor with the pattern 2–1–2–2–1–2–2. The raised leading note of harmonic minor is not part of this basic pattern.", "treble | 4/4 | A4/4 B4/4 C5/4 D5/4 | E5/4 F5/4 G5/4 A5/4"),
    ],
    "sevenths": [
        ("majorSeventh", "Großer Septakkord", "Major seventh chord", "Ein Dur-Dreiklang mit großer Septime über dem Grundton ergibt einen großen Septakkord. C–E–G–H ist ein eigenes Beispiel; die Septime ist ein Akkordton, nicht bloß eine zusätzliche Oktave.", "A major triad with a major seventh above the root forms a major seventh chord. C–E–G–B is an original example; the seventh is a chord member, not an extra octave.", "treble | 4/4 | (C4 E4 G4 B4)/1"),
        ("dominantSeventh", "Dominantseptakkord", "Dominant seventh chord", "Dur-Dreiklang plus kleine Septime ergibt die Struktur des Dominantseptakkords. G–H–D–F kann in C-Dur die Dominante bilden; der Akkordname allein bestimmt aber noch keine Tonart.", "A major triad plus a minor seventh forms a dominant seventh chord. G–B–D–F may act as the dominant in C major, but the chord label alone does not determine a key.", "treble | 4/4 | (G4 B4 D5 F5)/1"),
        ("minorSeventh", "Mollseptakkord", "Minor seventh chord", "Moll-Dreiklang plus kleine Septime bildet einen Mollseptakkord. D–F–A–C ist ein Beispiel; unterscheide Akkordqualität und harmonische Funktion im jeweiligen Kontext.", "A minor triad plus a minor seventh forms a minor seventh chord. D–F–A–C is one example; distinguish chord quality from harmonic function in context.", "treble | 4/4 | (D4 F4 A4 C5)/1"),
        ("halfDiminished", "Halbverminderter Septakkord", "Half-diminished seventh chord", "Verminderter Dreiklang plus kleine Septime ergibt einen halbverminderten Septakkord. H–D–F–A ist in C-Dur ein leitereigener Vierklang auf Stufe VII.", "A diminished triad plus a minor seventh forms a half-diminished seventh chord. B–D–F–A is a diatonic seventh chord on degree VII in C major.", "treble | 4/4 | (B3 D4 F4 A4)/1"),
    ],
    "functions": [
        ("tonic", "Tonika", "Tonic", "Die Tonika ist der Akkord auf Stufe I und ein möglicher Ruhepunkt der Tonart. In C-Dur ist C–E–G ein Beispiel; die Funktion folgt aus dem Tonartkontext, nicht aus einem isolierten Klang.", "The tonic is the chord on degree I and a possible point of rest in a key. C–E–G is an example in C major; its function depends on the key context, not isolated sound.", "treble | 4/4 | (C4 E4 G4)/1"),
        ("subdominant", "Subdominante", "Subdominant", "Die Subdominante liegt in der einfachen Durstufendeutung auf Stufe IV. F–A–C ist in C-Dur ein Beispiel; ihr Verlauf kann zur Dominante oder direkt zur Tonika führen.", "In a simple major-key analysis the subdominant is degree IV. F–A–C is an example in C major; it may move to the dominant or directly to the tonic.", "treble | 4/4 | (F4 A4 C5)/1"),
        ("dominant", "Dominante", "Dominant", "Die Dominante liegt in Dur auf Stufe V und kann zur Tonika führen. G–H–D in C-Dur zeigt diesen Bezug; eine römische Stufe und ein Funktionszeichen sind unterschiedliche Beschriftungen.", "The dominant is degree V in major and can lead to the tonic. G–B–D in C major shows that relation; a Roman numeral and a function symbol are different labels.", "treble | 4/4 | (G4 B4 D5)/1"),
        ("degreeContext", "Stufe und Kontext", "Degree and context", "Ein Akkord muss gegen den festgelegten Grundton der Tonart gelesen werden. Derselbe C-Dur-Dreiklang kann in C-Dur I, in G-Dur IV sein; die Aufgabe zeigt deshalb stets die Tonart.", "Read a chord against the stated tonic of the key. The same C-major triad may be I in C major and IV in G major; the exercise therefore states the key.", "treble | 4/4 | (C4 E4 G4)/2 (G4 B4 D5)/2"),
    ],
    "cadences": [
        ("authentic", "Authentische Schlusswendung", "Authentic cadence", "Die vereinfachte authentische Schlusswendung verläuft V–I. Diese Aufgaben klassifizieren nur die gezeigten Stufenfolgen; Lage, Melodiestimme und Schlusswirkung sind zusätzliche Fragen.", "The simplified authentic cadence moves V–I. These exercises classify the shown degree sequence; voicing, melodic line and strength of closure require separate analysis.", "treble | 4/4 | (G4 B4 D5)/2 (C4 E4 G4)/2"),
        ("plagal", "Plagale Schlusswendung", "Plagal cadence", "Die vereinfachte plagale Schlusswendung verläuft IV–I. F–A–C nach C–E–G illustriert das in C-Dur; die gezeigte Folge belegt keine bestimmte historische Gattung.", "The simplified plagal cadence moves IV–I. F–A–C followed by C–E–G illustrates it in C major; the sequence does not prove a historical genre.", "treble | 4/4 | (F4 A4 C5)/2 (C4 E4 G4)/2"),
        ("half", "Halbschluss", "Half cadence", "Ein Halbschluss endet in diesem Lehrmodell auf V, beispielsweise I–V. Er wirkt im Tonartkontext offen; das Etikett beschreibt die Akkordfolge, keine gemessene Hörerreaktion.", "A half cadence ends on V in this teaching model, for example I–V. It remains open within the key; the label describes the chord sequence, not a measured listener response.", "treble | 4/4 | (C4 E4 G4)/2 (G4 B4 D5)/2"),
        ("deceptive", "Trugschluss", "Deceptive cadence", "Beim einfachen Trugschluss führt V statt nach I zur Stufe VI. In C-Dur kann auf G–H–D ein A-Moll-Dreiklang folgen; andere Kontexte brauchen gesonderte Analyse.", "In a simple deceptive cadence V moves to VI instead of I. In C major, G–B–D may be followed by an A-minor triad; other contexts need separate analysis.", "treble | 4/4 | (G4 B4 D5)/2 (A4 C5 E5)/2"),
    ],
    "modulation": [
        ("pivot", "Gemeinsamer Akkord", "Pivot chord", "Ein gemeinsamer Akkord kann in zwei benachbarten Tonarten unterschiedliche Stufen tragen. Für eine Modulation genügt die Mehrdeutigkeit allein nicht; eine neue Tonika muss im Verlauf gestützt werden.", "A pivot chord can have different degrees in two neighbouring keys. Ambiguity alone does not prove modulation; the new tonic needs support in the musical passage.", "treble | 4/4 | (A4 C5 E5)/2 (D4 F#4 A4)/2"),
        ("tonicization", "Zwischendominante und Tonikalisierung", "Secondary dominant and tonicization", "Eine Zwischendominante richtet sich kurz auf einen anderen leitereigenen Akkord. Eine solche lokale Tonikalisierung ist nicht automatisch ein dauerhafter Tonartwechsel.", "A secondary dominant points briefly to another diatonic chord. Such local tonicization does not by itself establish a lasting key change.", "treble | 4/4 | (A4 C#5 E5)/2 (D4 F4 A4)/2"),
        ("newTonic", "Neue Tonika bestätigen", "Establish a new tonic", "Eine neue Tonika wird überzeugender, wenn Folgeakkorde, Leitton und Kadenz sie stützen. Der bloße Auftritt eines fremden Vorzeichens reicht als Nachweis nicht aus.", "A new tonic is more convincing when subsequent chords, a leading note and a cadence support it. A single foreign accidental is insufficient evidence.", "treble | 4/4 | (D4 F#4 A4)/2 (G4 B4 D5)/2"),
        ("commonTone", "Gemeinsamer Ton", "Common tone", "Ein gehaltener oder wiederholter Ton kann zwei harmonische Bereiche verbinden. Er ist ein Verbindungsmittel, aber keine eindeutige Modulationsdiagnose ohne den weiteren Satzverlauf.", "A held or repeated pitch can connect two harmonic regions. It is a device for continuity, not an unambiguous modulation diagnosis without the wider passage.", "treble | 4/4 | (C4 E4 G4)/2 (A4 C5 E5)/2"),
    ],
    "dictation": [
        ("contour", "Melodieverlauf notieren", "Notate melodic contour", "Höre zuerst den Bezugston und die Richtung der folgenden Töne. Im einfachen Diktat werden vier Töne erfasst; prüfe jeden Ton gegen das Hörbeispiel statt nur die Kontur zu raten.", "First hear the reference pitch and the direction of subsequent notes. The short dictation captures four pitches; check each one against the clip instead of guessing only the contour.", "treble | 4/4 | C4/4 D4/4 E4/4 D4/4"),
        ("rhythm", "Rhythmus mitschreiben", "Write down the rhythm", "Höre den Grundschlag und unterscheide Viertel, Halbe und zwei Achtel. Vier Ereignisse füllen in den angebotenen Mustern einen 4/4-Takt; trage die Dauern in Hörreihenfolge ein.", "Hear the beat and distinguish quarters, halves and paired eighths. Four events fill a 4/4 bar in the offered patterns; enter durations in heard order.", "treble | 4/4 | C4/8 D4/8 E4/4 G4/2"),
        ("pitchCheck", "Tonhöhe prüfen", "Check a performed pitch", "Beim Blattsingen und Nachspielen vergleicht die Übung erkannte Tonhöhen mit dem vorgegebenen Ziel. Ein Hilfston zählt als Hinweis; Eingabegenauigkeit und Latenz müssen auf echten Geräten geprüft werden.", "Sight-singing and playback compare detected pitches with the written target. A help tone counts as a hint; input accuracy and latency still need testing on real devices.", "treble | 4/4 | C4/4 E4/4 G4/4 E4/4"),
        ("errorCheck", "Diktat kontrollieren", "Review a dictation", "Spiele die Quelle erneut und prüfe jede Position nach der ersten Eingabe. Eine richtige Kontur ersetzt weder exakte Tonhöhen noch Dauern; Fehlerwiederholungen verwenden neue Varianten.", "Replay the source and check each position after the first entry. Correct contour does not replace exact pitches or durations; error review uses new variants.", "treble | 4/4 | C4/4 E4/4 D4/4 G4/4"),
    ],
    "phrases": [
        ("motive", "Motiv", "Motive", "Ein Motiv ist eine kurze, wiedererkennbare musikalische Gestalt. Wiederholung, Verschiebung und Veränderung können eine Beziehung herstellen; zwei gleiche Töne allein beweisen kein ausgearbeitetes Motiv.", "A motive is a short recognizable musical idea. Repetition, displacement and change can establish a relation; two matching notes alone do not prove a developed motive.", "treble | 4/4 | C4/4 D4/4 E4/2 | C4/4 D4/4 G4/2"),
        ("phrase", "Phrase", "Phrase", "Eine Phrase ist ein zusammenhängender musikalischer Abschnitt mit wahrnehmbarer Gliederung. Phrasierungsbogen, Atem und harmonischer Verlauf können Hinweise geben, aber kein einzelnes Zeichen entscheidet allein.", "A phrase is a coherent musical span with perceptible articulation. Slurs, breath and harmony may offer clues, but no single sign settles its boundary on its own.", "treble | 4/4 | C4/4 D4/4 E4/4 G4/4 | A4/4 G4/4 E4/2"),
        ("antecedent", "Vordersatz", "Antecedent phrase", "Ein Vordersatz eröffnet in einem einfachen periodischen Modell eine Frage-Antwort-Beziehung und endet oft weniger geschlossen. Das Modell beschreibt eine mögliche Gestaltung, keine universelle Regel aller Musik.", "In a simple period model an antecedent opens a question-and-answer relation and often ends less conclusively. The model describes one possible design, not a universal rule for all music.", "treble | 4/4 | C4/4 E4/4 G4/4 D5/4 | C5/2 B4/2"),
        ("consequent", "Nachsatz", "Consequent phrase", "Ein Nachsatz nimmt Material des Vordersatzes auf und führt in diesem Modell zu einem deutlicheren Abschluss. Vergleiche Anfang, Länge und Schluss, statt nur zwei gleich lange Teile zu zählen.", "A consequent takes up material from the antecedent and reaches a clearer close in this model. Compare opening, length and ending rather than merely counting two equal spans.", "treble | 4/4 | C4/4 E4/4 G4/4 D5/4 | B4/4 G4/4 C5/2"),
    ],
    "forms": [
        ("binary", "Zweiteilige Form", "Binary form", "Eine zweiteilige Form besitzt zwei größere Abschnitte, schematisch A–B. Wiederholungszeichen oder Tonartwechsel können die Gliederung stützen; gleiche Taktzahl ist keine Pflicht.", "Binary form has two larger sections, schematically A–B. Repeat signs or a change of key may support the division; equal bar counts are not required.", "treble | 4/4 | C4/4 D4/4 E4/4 G4/4 | F4/4 E4/4 D4/4 C4/4"),
        ("ternary", "Dreiteilige Form", "Ternary form", "Bei A–B–A kehrt das Anfangsmaterial nach einem kontrastierenden Mittelteil zurück. Die Wiederkehr kann verändert sein; eine genaue Formanalyse vergleicht mehr als nur die ersten Töne.", "In A–B–A, opening material returns after a contrasting middle. The return may be altered; a careful form analysis compares more than the first notes.", "treble | 4/4 | C4/4 E4/4 G4/4 E4/4 | D4/4 F4/4 A4/4 F4/4 | C4/4 E4/4 G4/4 E4/4"),
        ("rondo", "Rondo-Grundidee", "Basic rondo idea", "Ein Rondo bringt einen wiederkehrenden Refrain zwischen kontrastierenden Abschnitten, etwa A–B–A–C–A. Die Buchstaben stehen für musikalisches Material, nicht automatisch für gleich lange Takte.", "A rondo places a recurring refrain between contrasting sections, for example A–B–A–C–A. The letters denote musical material, not necessarily equal numbers of bars.", "treble | 4/4 | C4/4 E4/4 G4/4 E4/4 | D4/4 F4/4 A4/4 F4/4 | C4/4 E4/4 G4/4 E4/4"),
        ("variation", "Variation", "Variation", "Eine Variation verändert erkennbares Ausgangsmaterial, etwa Rhythmus, Register oder Satz. Sie kann dessen Kontur oder Harmonik bewahren; bloße Wiederholung ohne Änderung ist noch keine Variation.", "A variation changes recognizable source material, perhaps its rhythm, register or texture. It may preserve contour or harmony; exact repetition without change is not yet variation.", "treble | 4/4 | C4/4 D4/4 E4/2 | C5/8 D5/8 E5/2 r/4"),
    ],
    "instrumentFamilies": [
        ("strings", "Streichinstrumente", "String instruments", "Violine, Viola, Violoncello und Kontrabass gehören zur Orchester-Streicherfamilie. Tonumfang, Spielweise und Register unterscheiden sich; ein Klaviermodell bildet ihre Klangfarbe nicht ab.", "Violin, viola, cello and double bass belong to the orchestral string family. Range, technique and register differ; a piano model does not reproduce their timbre.", "treble | 4/4 | G4/4 A4/4 B4/4 C5/4"),
        ("woodwinds", "Holzblasinstrumente", "Woodwinds", "Flöte, Oboe, Klarinette und Fagott zählen im Orchester zu den Holzbläsern. Die Familie ist eine Spiel- und Orchesterkategorie; Material allein erklärt die Einordnung nicht.", "Flute, oboe, clarinet and bassoon are orchestral woodwinds. The family is a performance and orchestration category; material alone does not determine membership.", "treble | 4/4 | C5/4 B4/4 A4/4 G4/4"),
        ("brass", "Blechblasinstrumente", "Brass instruments", "Trompete, Horn, Posaune und Tuba bilden typische Orchester-Blechbläser. Die Lippen regen die Luftsäule an; Instrumentenname und klingende Lage sind getrennte Informationen.", "Trumpet, horn, trombone and tuba are common orchestral brass instruments. The player's lips excite the air column; instrument name and sounding register are distinct information.", "bass | 4/4 | C3/4 E3/4 G3/4 C4/4"),
        ("percussion", "Schlaginstrumente", "Percussion instruments", "Schlaginstrumente umfassen Instrumente mit bestimmter Tonhöhe wie Pauken und solche ohne einzelne feste Tonhöhe wie viele Becken. Eine allgemeine Familienangabe legt die Notation nicht fest.", "Percussion includes pitched instruments such as timpani and instruments without a single fixed pitch such as many cymbals. A family label alone does not determine notation.", "bass | 4/4 | C3/4 r/4 C3/4 r/4"),
    ],
    "instrumentScores": [
        ("concertPitch", "Klingende Tonhöhe", "Concert pitch", "Klingende Tonhöhe bezeichnet den tatsächlich erzeugten Ton. Beim Vergleich mit einer transponierenden Stimme muss ihre notierte Tonhöhe in die klingende Lage umgerechnet werden.", "Concert pitch is the pitch actually sounded. When comparing a transposing part, convert its written pitch to sounding pitch.", "treble | 4/4 | Bb4/1"),
        ("writtenPitch", "Notierte Tonhöhe", "Written pitch", "Notierte Tonhöhe ist das Zeichen in der Einzelstimme. Bei einer B-Klarinette erklingt ein notiertes C als B einen Ganzton tiefer; das Beispiel ist schematisch.", "Written pitch is the note in the instrumental part. On B-flat clarinet, written C sounds as B-flat a whole step lower; the example is schematic.", "treble | 4/4 | C5/1"),
        ("transposition", "Transposition bestimmen", "Determine transposition", "Vergleiche bei transponierenden Instrumenten notierte und klingende Tonhöhe mit Richtung und Intervall. Eine B-Klarinette klingt einen großen Sekundschritt tiefer als notiert; andere Instrumente benötigen eigene Regeln.", "Compare written and sounding pitches by direction and interval for transposing instruments. A B-flat clarinet sounds a major second below written pitch; other instruments need their own rules.", "treble | 4/4 | C5/2 Bb4/2"),
        ("scoreOrder", "Partitur lesen", "Read a full score", "Eine Partitur ordnet mehrere Stimmen gleichzeitig. Lies Schlüssel, Instrumentenname, Taktposition und Transposition jeder Zeile, bevor du notierte Töne als gemeinsamen Klang vergleichst.", "A full score aligns several parts in time. Check each line's clef, instrument name, bar position and transposition before comparing written notes as simultaneous sound.", "treble | 4/4 | C5/2 D5/2"),
    ],
    "jazzHarmony": [
        ("leadSheet", "Lead Sheet und Akkordsymbol", "Lead sheet and chord symbol", "Ein Lead Sheet zeigt gewöhnlich Melodie und Akkordsymbole; es legt nicht jede Begleitstimme fest. Ein Symbol wie G7 benennt einen Akkordtyp, seine genaue Lage bleibt eine Aufführungsentscheidung.", "A lead sheet typically gives melody and chord symbols; it does not prescribe every accompaniment part. A symbol such as G7 names a chord type while voicing remains a performance choice.", "treble | 4/4 | G4/4 B4/4 D5/4 F5/4"),
        ("twoFiveOne", "II–V–I", "II–V–I", "In C-Dur kann Dm7–G7–Cmaj7 eine II–V–I-Folge bilden. Stufen, Septakkordqualitäten und Tonart müssen gemeinsam gelesen werden; die Folge ist ein Modell, kein Stilnachweis.", "In C major, Dm7–G7–Cmaj7 may form a ii–V–I progression. Read degrees, seventh-chord qualities and key together; the progression is a model, not proof of style.", "treble | 4/4 | (D4 F4 A4 C5)/4 (G4 B4 D5 F5)/4 (C4 E4 G4 B4)/2"),
        ("backbeat", "Backbeat", "Backbeat", "Ein Backbeat betont in vielen Pop- und Rockkontexten die Zählzeiten zwei und vier im Vierertakt. Instrumentierung und Groove verändern die Wirkung; nicht jede populäre Musik verwendet dieses Muster.", "In many pop and rock contexts a backbeat emphasizes beats two and four of quadruple metre. Instrumentation and groove affect the result; not all popular music uses this pattern.", "treble | 4/4 | C4/4 E4/4 G4/4 E4/4"),
        ("loop", "Harmonischer Loop", "Harmonic loop", "Ein harmonischer Loop wiederholt eine Akkordfolge und kann über mehrere Abschnitte gleich bleiben. Die Wiederholung allein bestimmt weder Form noch Genre; achte auf Melodie, Rhythmus und Produktion.", "A harmonic loop repeats a chord progression and may persist across sections. Repetition alone determines neither form nor genre; attend to melody, rhythm and production.", "treble | 4/4 | (C4 E4 G4)/2 (A4 C5 E5)/2 | (F4 A4 C5)/2 (G4 B4 D5)/2"),
    ],
    "historyMethods": [
        ("manuscript", "Handschrift als Quelle", "Manuscript as source", "Eine Handschrift kann eine bestimmte Überlieferungsstufe zeigen. Datierung, Schreiber, Herkunft und spätere Änderungen müssen geprüft werden; das Blatt ist kein unmittelbarer Mitschnitt einer Aufführung.", "A manuscript documents a stage of transmission. Date, copyist, provenance and later changes need examination; the page is not a direct recording of a performance.", "treble | 4/4 | C4/4 D4/4 E4/4 F4/4"),
        ("edition", "Edition und Eingriff", "Edition and intervention", "Eine Edition trifft Entscheidungen über Lesarten, Vorzeichen und Ergänzungen. Unterscheide Quellenbefund und Herausgeberzusatz; ein moderner Druck ist nicht automatisch der ursprüngliche Wortlaut.", "An edition makes decisions about readings, accidentals and additions. Separate source evidence from editorial intervention; a modern print is not automatically the original text.", "treble | 4/4 | C4/4 Eb4/4 G4/4 C5/4"),
        ("recordingDate", "Aufnahme und Werkdatum", "Recording date and work date", "Das Datum einer Aufnahme bezeichnet nicht das Entstehungsjahr eines Werkes. Eine Aufnahme belegt eine Aufführung oder Produktion zu ihrer Zeit; Klang allein datiert die Komposition nicht sicher.", "The date of a recording is not the date of composition. A recording documents a performance or production at its own time; sound alone cannot securely date the work.", "treble | 4/4 | G4/4 F4/4 E4/4 C4/4"),
        ("oralHistory", "Mündliche Erinnerung", "Oral history", "Ein Interview erschließt Perspektiven von Beteiligten, enthält aber Erinnerungs- und Auswahlprozesse. Vergleiche es mit anderen Quellen und nenne Unsicherheit, statt eine einzige Stimme zur Gesamtgeschichte zu machen.", "An interview gives access to participants' perspectives but is shaped by memory and selection. Compare it with other sources and state uncertainty rather than treating one voice as the whole history.", "treble | 4/4 | C4/4 E4/4 G4/4 E4/4"),
    ],
}

